SELECT code, level, title, summary, series_code, seq FROM lesson_text WHERE subject_id = CAST(:subject_id AS INTEGER) AND (:series_code = '' OR series_code = :series_code) AND (:level = '' OR level = :level) AND (:keyword = '' OR instr(code, :keyword) > 0 OR instr(title, :keyword) > 0 OR instr(COALESCE(summary, ''), :keyword) > 0 OR EXISTS (SELECT 1 FROM lesson_item_link l JOIN kg_item i ON i.code = l.item_code WHERE l.subject_id = CAST(:subject_id AS INTEGER) AND i.subject_id = CAST(:subject_id AS INTEGER) AND l.lesson_code = lesson_text.code AND instr(i.name, :keyword) > 0)) ORDER BY seq ASC, id ASC
